style.css:
@-moz-document domain("youtube.com") {
/* ==========================================================================
       YOUTUBE JULY 2012 RETRO THEME FOR STYLISH
       ========================================================================== */

    /* --- 1. Global Page Backgrounds & Typography --- */
    html, 
    body, 
    ytd-app, 
    #page-manager,
    #columns.ytd-watch-flexy,
    ytd-browse,
    ytd-two-column-browse-results-renderer {
        background-color: #EFEFEF !important; /* Classic 2012 soft gray backdrop */
        font-family: Arial, Helvetica, sans-serif !important;
    }

    /* --- 2. Top Header / Navigation Bar --- */
    #masthead-container, 
    ytd-masthead,
    #container.ytd-masthead {
        background-color: #F1F1F1 !important;
        border-bottom: 1px solid #E2E2E2 !important;
        box-shadow: none !important;
    }

    /* Search Input Field */
    #search-form, 
    ytd-searchbox #container.ytd-searchbox {
        background-color: #FFFFFF !important;
        border: 1px solid #CCCCCC !important;
        border-radius: 0px !important;
        box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.1) !important;
    }

    /* Search Button */
    #search-icon-legacy.ytd-searchbox {
        background-color: #F8F8F8 !important;
        border: 1px solid #CCCCCC !important;
        border-left: none !important;
        border-radius: 0px !important;
    }

    /* --- 3. White Video & Content Cards --- */
    #primary, 
    #secondary, 
    ytd-watch-metadata, 
    ytd-rich-grid-renderer,
    ytd-watch-flexy[flexy] #primary.ytd-watch-flexy {
        background-color: #FFFFFF !important;
        border-radius: 0px !important;
    }

    /* --- 4. Remove All Modern Rounded Corners --- */
    *, 
    ytd-thumbnail, 
    #thumbnail, 
    #chip, 
    yt-chip-cloud-chip-renderer, 
    button, 
    ytd-button-renderer,
    ytd-guide-entry-renderer,
    yt-button-shape {
        border-radius: 0px !important;
    }

    /* --- 5. Classic 2012 Red Subscribe Button --- */
    ytd-subscribe-button-renderer button,
    #subscribe-button paper-button,
    yt-button-shape a[aria-label*="Subscribe"],
    yt-button-shape button[aria-label*="Subscribe"] {
        background-color: #CC181E !important; /* Original 2012 YouTube Red */
        color: #FFFFFF !important;
        border: 1px solid #B01016 !important;
        border-radius: 2px !important;
        font-weight: bold !important;
        text-transform: uppercase !important;
        font-size: 11px !important;
    }

    ytd-subscribe-button-renderer button:hover {
        background-color: #B01016 !important;
    }

    /* --- 6. Video Player Clean-Up --- */
    /* Remove modern ambient background glow */
    #cinematics, 
    .ytp-gradient-bottom, 
    .ytp-gradient-top {
        display: none !important;
    }

    /* Sharp 1px Borders around Video Thumbnails */
    ytd-thumbnail #thumbnail.ytd-thumbnail {
        border: 1px solid #D3D3D3 !important;
        padding: 2px !important;
        background-color: #FFFFFF !important;
    }

    /* --- 7. Sidebar Navigation --- */
    ytd-guide-renderer, 
    #mini-guide,
    #guide-content {
        background-color: #FBFBFB !important;
        border-right: 1px solid #E2E2E2 !important;
    }

    /* Links and Title Colors */
    #video-title, 
    .ytd-video-meta-block, 
    #channel-name,
    #video-title.ytd-rich-grid-media {
        color: #333333 !important;
        font-family: Arial, Helvetica, sans-serif !important;
    }

    a.yt-simple-endpoint:hover {
        color: #128EE9 !important; /* Classic link hover blue */
    }
}
